\providecommand{\stxOuttro}{}\renewcommand{\stxOuttro}[1]{#1}
\providecommand{\stxTitle}{}\renewcommand{\stxTitle}[1]{#1}
% Comment next line to show outtros
\renewcommand{\stxOuttro}[1]{}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\stxKnowl{
Determine if each of the statements below is true or false.

\begin{enumerate}
\item
\stxKnowl{
If \(q\) is a multiple of \(7\), then \(5q\) is a multiple of \(7\).

\stxOuttro{
True

}
}

\item
\stxKnowl{
\(4\) is a divisor of \(48\)

\stxOuttro{
True

}
}

\item
\stxKnowl{
If \(f\) divides \(49\), then \(f\) divides \(7\).

\stxOuttro{
False

}
}

\item
\stxKnowl{
\(40\) is a multiple of \(5\)

\stxOuttro{
True

}
}

\item
\stxKnowl{
If \(7\) is a divisor of \(j\) and \(2\) is a divisor of \(f\), then \(9\) is a divisor of \(j + f\).

\stxOuttro{
False

}
}

\item
\stxKnowl{
\(30\) divides \(3\)

\stxOuttro{
False

}
}

\item
\stxKnowl{
\(2\) is a factor of \(4\)

\stxOuttro{
True

}
}

\item
\stxKnowl{
If \(d\) is a factor of \(9\) and \(d\) is not a factor of \(f\), then \(d\) is not a factor of \(9 + f\).

\stxOuttro{
True

}
}

\end{enumerate}
}
